<script setup>
import {computed,ref,reactive,watch} from 'vue';
import EntityForm from './EntityForm.vue';
import AppDialog from './AppDialog.vue';import FormField from './FormField.vue';import PatternThumbnail from './PatternThumbnail.vue';
import {state,dispatch,notify} from '../state';import {t,errorText} from '../i18n';
import {BUILTIN_MOTIFS,SUPPORTED_TEXT,builtinMotif,bitmapText,unsupportedText,stampInsert,selectionMotif} from '../../core/editor-inserts.mjs';
const props=defineProps({pattern:{type:Object,required:true},selection:Object,cursor:Object,selectedColor:Number,apply:{type:Function,required:true}}),emit=defineEmits(['close']);
const tab=ref('motif'),chosen=ref('builtin:diamond'),content=ref('RICAMO'),color=ref(props.selectedColor??0),mode=ref('empty'),position=reactive({x:(props.cursor?.x??0)+1,y:(props.cursor?.y??0)+1}),textSettings=reactive({spacing:1,lineSpacing:2,scale:1}),name=ref(''),category=ref(''),categoryFilter=ref(''),metadataForm=ref(null),busy=ref(false),error=ref(''),pendingDelete=ref('');
const motifs=computed(()=>state.value.settings.preferences?.editorMotifs?.items??[]),unsupported=computed(()=>unsupportedText(content.value)),selectedMotif=computed(()=>motifs.value.find(row=>`user:${row.id}`===chosen.value));
const categories=computed(()=>[...new Set(motifs.value.map(row=>row.category??'').filter(Boolean))].sort((a,b)=>a.localeCompare(b)));
const filteredMotifs=computed(()=>motifs.value.filter(row=>!categoryFilter.value||(categoryFilter.value==='none'?!row.category:categoryFilter.value===`category:${row.category}`)));
watch(filteredMotifs,rows=>{if(chosen.value.startsWith('user:')&&!rows.some(row=>`user:${row.id}`===chosen.value))chosen.value='builtin:diamond'});
const metadataFields=computed(()=>[{key:'name',label:t('motifName'),required:true,max:120},{key:'category',label:t('motifCategory'),help:t('motifCategoryHelp'),max:120}]);
function editMetadata(){const row=selectedMotif.value;metadataForm.value={initial:{name:row.name,category:row.category??''},submit:async data=>{await dispatch('motif.save',{id:row.id,...data});categoryFilter.value='';chosen.value=`user:${row.id}`;notify()}};}
const source=computed(()=>{try{const selected=props.pattern.colors[color.value];return{value:tab.value==='text'?bitmapText(content.value,selected,textSettings):chosen.value.startsWith('builtin:')?builtinMotif(chosen.value.slice(8),selected):selectedMotif.value?.revision}}catch(error){return{error}}});
const preview=computed(()=>{if(!source.value.value)return{};try{return{value:stampInsert(props.pattern,source.value.value,position.x-1,position.y-1,{mode:mode.value})}}catch(error){return{error}}});
const selectionSource=computed(()=>{if(!props.selection)return{};try{return{value:selectionMotif(props.pattern,props.selection)}}catch(error){return{error}}});
function friendly(caught){const keys={text_unsupported:'insertUnsupported',insert_bounds:'insertBounds',insert_color:'insertChooseColour',motif_crossing:'motifCrossing',motif_dimensions:'motifDimensions',motif_empty:'motifEmpty',motif_capacity:'motifCapacity',data_too_large:'motifCapacity','pattern.dimensions':'insertBounds','pattern.paletteLimit':'paletteLimit'};return keys[caught?.code]?t(keys[caught.code]):errorText(caught);}
async function saveSelection(){if(!selectionSource.value.value||!name.value.trim())return;busy.value=true;error.value='';try{const id=crypto.randomUUID();await dispatch('motif.save',{id,name:name.value,category:category.value,revision:JSON.parse(JSON.stringify(selectionSource.value.value))});categoryFilter.value='';chosen.value=`user:${id}`;tab.value='motif';name.value='';notify();}catch(caught){error.value=friendly(caught)}finally{busy.value=false}}
async function remove(){busy.value=true;error.value='';try{await dispatch('motif.remove',{id:pendingDelete.value});pendingDelete.value='';chosen.value='builtin:diamond';notify()}catch(caught){error.value=friendly(caught)}finally{busy.value=false}}
function insert(){if(!preview.value.value)return;const selected=JSON.parse(JSON.stringify(source.value.value)),x=position.x-1,y=position.y-1,placement=mode.value;if(props.apply(pattern=>stampInsert(pattern,selected,x,y,{mode:placement}).revision))emit('close');}
</script>
<template>
 <AppDialog :title="t('editorInserts')" wide :busy="busy" @close="emit('close')">
  <div class="stack">
  <p v-if="error" class="notice error" role="alert">{{error}}</p>
  <FormField :label="t('insertKind')" v-slot="{id}"><select :id="id" v-model="tab"><option value="motif">{{t('motifs')}}</option><option value="text">{{t('insertText')}}</option></select></FormField>
  <template v-if="tab==='motif'"><FormField v-if="motifs.length" :label="t('motifCategoryFilter')" v-slot="{id}"><select :id="id" v-model="categoryFilter"><option value="">{{t('all')}}</option><option value="none">{{t('motifUncategorized')}}</option><option v-for="entry in categories" :key="entry" :value="`category:${entry}`">{{entry}}</option></select></FormField><p v-if="motifs.length&&!filteredMotifs.length" class="notice">{{t('noResults')}}</p><FormField :label="t('motifs')" v-slot="{id}"><select :id="id" v-model="chosen"><optgroup :label="t('originalMotifs')"><option v-for="(_,key) in BUILTIN_MOTIFS" :key="key" :value="`builtin:${key}`">{{t(`motif_${key}`)}}</option></optgroup><optgroup v-if="filteredMotifs.length" :label="t('savedMotifs')"><option v-for="motif in filteredMotifs" :key="motif.id" :value="`user:${motif.id}`">{{motif.name}} · {{motif.revision.width}} × {{motif.revision.height}}</option></optgroup></select></FormField>
   <button v-if="selectedMotif" class="button text small" @click="editMetadata">{{t('motifEditMetadata')}}</button><button v-if="selectedMotif" class="button text small" @click="pendingDelete=selectedMotif.id">{{t('motifRemove')}}</button><div v-if="pendingDelete" class="notice warning"><p>{{t('motifRemoveConfirm')}}</p><div class="actions"><button class="button small" @click="pendingDelete=''">{{t('cancel')}}</button><button class="button small danger" :disabled="busy" @click="remove">{{t('confirm')}}</button></div></div>
  </template>
  <template v-else><FormField :label="t('insertText')" :help="t('bitmapAlphabetHelp')" v-slot="{id,describedby}"><textarea :id="id" v-model="content" :aria-describedby="describedby" maxlength="500" rows="3" /></FormField><button class="button text small" @click="content=content.toUpperCase()">{{t('bitmapUppercase')}}</button><p v-if="unsupported.length" class="notice warning" role="status">{{t('insertUnsupported')}}: <strong>{{unsupported.map(c=>JSON.stringify(c)).join(', ')}}</strong></p><p class="field-help">{{t('supportedCharacters')}}: {{SUPPORTED_TEXT}}</p><div class="form-grid"><FormField v-for="key in ['spacing','lineSpacing','scale']" :key="key" :label="t(`bitmap_${key}`)" v-slot="{id}"><input :id="id" v-model.number="textSettings[key]" type="number" :min="key==='scale'?1:0" :max="key==='scale'?4:key==='spacing'?8:12" /></FormField></div></template>
  <FormField v-if="tab==='text'||chosen.startsWith('builtin:')" :label="t('color')" v-slot="{id}"><select :id="id" v-model.number="color"><option v-for="(entry,index) in pattern.colors" :key="index" :value="index">{{entry.symbol}} · {{entry.brand}} {{entry.code}} · {{entry.name}}</option></select></FormField>
  <div class="form-section"><div class="form-grid"><FormField :label="t('insertColumn')" v-slot="{id}"><input :id="id" v-model.number="position.x" type="number" min="1" :max="pattern.width" /></FormField><FormField :label="t('insertRow')" v-slot="{id}"><input :id="id" v-model.number="position.y" type="number" min="1" :max="pattern.height" /></FormField></div><FormField :label="t('insertPlacement')" :help="t('insertPlacementHelp')" v-slot="{id,describedby}"><select :id="id" v-model="mode" :aria-describedby="describedby"><option value="empty">{{t('insertEmptyOnly')}}</option><option value="overwrite">{{t('insertOverwrite')}}</option></select></FormField></div>
  <p v-if="source.error||preview.error" class="notice warning" role="status">{{friendly(source.error||preview.error)}}</p>
  <template v-if="source.value"><h3>{{t('preview')}} · {{source.value.width}} × {{source.value.height}}</h3><PatternThumbnail :revision="preview.value?.insert??source.value" :label="t('insertExactPreview')" /><p v-if="preview.value" class="notice">{{t('insertImpact',{added:preview.value.added,removed:preview.value.impact.removedFull+preview.value.impact.removedHalf+preview.value.impact.removedBack,skipped:preview.value.impact.skippedFull+preview.value.impact.skippedHalf+preview.value.impact.skippedBack})}}</p></template>
  <details class="form-section"><summary>{{t('motifSaveSelection')}}</summary><p class="field-help">{{t('motifSaveHelp')}}</p><p v-if="!selection" class="notice">{{t('motifSelectFirst')}}</p><p v-else-if="selectionSource.error" class="notice warning">{{friendly(selectionSource.error)}}</p><template v-else-if="selectionSource.value"><PatternThumbnail :revision="selectionSource.value" :label="t('selection')" /><FormField :label="t('motifName')" v-slot="{id}"><input :id="id" v-model="name" maxlength="120" /></FormField><FormField :label="t('motifCategory')" :help="t('motifCategoryHelp')" v-slot="{id,describedby}"><input :id="id" v-model="category" maxlength="120" :aria-describedby="describedby" /></FormField><button class="button" :disabled="busy||!name.trim()" @click="saveSelection">{{t('motifSaveSelection')}}</button></template></details>
  </div>
  <template #footer><button class="button" :disabled="busy" @click="emit('close')">{{t('cancel')}}</button><button class="button primary" :disabled="busy||!preview.value||preview.value.added===0" @click="insert">{{t('insertApply')}}</button></template>
 </AppDialog>
 <EntityForm v-if="metadataForm" :title="t('motifEditMetadata')" :fields="metadataFields" :initial="metadataForm.initial" :submit="metadataForm.submit" @close="metadataForm=null" @saved="metadataForm=null" />
</template>
